/**
 * dsh-provider-usage — 配置归一化（单一职责：默认值 / schemastery schema / normalizeConfig）。
 *
 * 自 index.ts 抽离，导出面由 index.ts 转发 re-export
 * 保持不变（外部消费者仍从 lib/index.js 导入）。
 */

import z from "schemastery";
import { OPENCODE_GO_PROVIDER } from "./provider.ts";

export const DEFAULT_CONFIG = {
  adapter: "",
  staticPath: "",
  provider: OPENCODE_GO_PROVIDER,
  apiEndpoint: "",
  apiKey: "",
  historyDir: "",
  warmupIntervalMs: 300000,
  // 由 60000 下调至 30000——峰谷徽标倒计时跨时段边界的展示翻转延迟
  // = 宿主缓存 + 客户端轮询（60s）+ 渲染余量，缓存减半使端到端 ≤95s 可达。
  cacheDurationMs: 30000,
  // 2s→5s——commandcode 等三请求并行适配器在远端慢时 2s 频繁超时；
  // safeFetchData 为 Promise.race+Abort 纯异步超时，不阻塞主进程（超时会
  // 经合并信号真正 abort 底层 fetch）；
  // 取数锁为 per-provider 粒度，排队仅发生在同一 provider 内部，
  // 最坏 n×5s 只限单 provider 的并发请求，跨 provider 完全并行。
  fetchTimeoutMs: 5000,
  autoReload: true,
  maxAgeDays: 30,
  maxSizeMB: 20,
  // 会话用量趋势：聚合分片保留天数（日切压实后按天留存，明细仅当日）
  trendRetentionDays: 180,
};

/** 只接受布尔值的配置键（客户端 UI 按它渲染开关）；与 schema 里的 `z.boolean()` 字段一一对应。 */
export const BOOLEAN_KEYS: readonly string[] = ["autoReload"];

/**
 * 非负整数键及其上界（默认值不得越界）。上界取自下面 `normalizeConfig` 里的 `Math.min`——
 * 两处都是声明，config-matrix 门禁的 N4 断言它们与 DEFAULT_CONFIG 一致，漂移即红。
 *
 * 只列**有产品上界**的键：`warmupIntervalMs` / `cacheDurationMs` 只有下界（60000 / 5000），
 * 上界是机器极限而非产品约束，列进来等于编一个假上界；`fetchTimeoutMs` 固定不开放配置。
 */
export const COUNT_LIMITS: Record<string, number> = {
  maxAgeDays: 365,
  maxSizeMB: 500,
  trendRetentionDays: 3650,
};

export interface NormalizedConfig {
  adapter: string;
  staticPath: string;
  provider: string;
  apiEndpoint: string;
  apiKey: string;
  historyDir: string;
  warmupIntervalMs: number;
  cacheDurationMs: number;
  fetchTimeoutMs: number;
  autoReload: boolean;
  maxAgeDays: number;
  maxSizeMB: number;
  trendRetentionDays: number;
}

/**
 * 插件配置 schema（schemastery 对象；宿主设置面经 shared 接缝以 unknown 消费）。
 *
 * 显式 `z<平面接口>` 声明保持原样，RHS 末尾单重 as 收口（lan-proxy model.ts 同款，
 * dsh 0.1.7-rc.1 跟进时的历史说明）：bump 后本包编译程序内同时存在 schemastery@3.18.0（直引，
 * `z` 值的实际解析）与 @deepseek-ai/schemastery@3.18.4（经 dsh-settings 0.1.7 类型层
 * 传入）的 `declare global namespace Schemastery`；合并后 `.default()` 的输出侧携带
 * Volatile 包装（SchemaOutput），直接赋值判红（TS2322）；裸推断引用未导入的 fork
 * 模块名，声明发射不可移植（TS2883）；`z<any>` 退路被提交钩子终结
 *（@typescript-eslint/no-explicit-any，长久性错误）。as 是纯类型擦除：值面从未调用
 * .volatile()，运行时无此物；对外类型面与当时的 0.1.7-rc.1 目标契约一致（rc.2 仍沿用该类型面），零行为变化。平面形状另由
 * NormalizedConfig 契约化，键集一致性由 unit-config 回归断言与 config-matrix 门禁锁定。
 */
export const Config: z<{
  adapter: string;
  staticPath: string;
  provider: string;
  apiEndpoint: string;
  warmupIntervalMs: number;
  cacheDurationMs: number;
  fetchTimeoutMs: number;
  autoReload: boolean;
  maxAgeDays: number;
  maxSizeMB: number;
  trendRetentionDays: number;
}> = z.object({
  adapter: z
    .string()
    .default("")
    .description("用户适配器 mjs 文件路径（兼容配置声明；推荐经设置页「用量统计」添加）"),
  staticPath: z.string().default("").description("API 路径（如 /v1/usage；config.adapter 模式用）"),
  provider: z.string().default(OPENCODE_GO_PROVIDER).description("关联的模型 provider 名"),
  apiEndpoint: z
    .string()
    .default("")
    .description("API 基础地址（可选，不填使用内置默认或模型配置链）")
    .disabled(true),
  warmupIntervalMs: z
    .number()
    .default(DEFAULT_CONFIG.warmupIntervalMs)
    .description("后台预热间隔毫秒")
    .disabled(true),
  cacheDurationMs: z
    .number()
    .default(DEFAULT_CONFIG.cacheDurationMs)
    .description("缓存新鲜度毫秒")
    .disabled(true),
  fetchTimeoutMs: z
    .number()
    .default(DEFAULT_CONFIG.fetchTimeoutMs)
    .description("取数超时毫秒")
    .disabled(true),
  autoReload: z
    .boolean()
    .default(true)
    .description("热更新开关（编辑适配器 mjs 后自动重新加载；默认开启，可显式 false 关闭）"),
  maxAgeDays: z
    .number()
    .default(DEFAULT_CONFIG.maxAgeDays)
    .description("历史数据保留天数")
    .disabled(true),
  maxSizeMB: z
    .number()
    .default(DEFAULT_CONFIG.maxSizeMB)
    .description("历史数据大小上限（MB）")
    .disabled(true),
  trendRetentionDays: z
    .number()
    .default(DEFAULT_CONFIG.trendRetentionDays)
    .description("会话用量趋势聚合保留天数")
    .disabled(true),
  // 末尾 as 收口（lan-proxy model.ts 同款，见文件头注释）：合并后的 Mode 条件类型
  // 使直接赋值判红，as 保持对外类型面恒为 z<平面接口>，值面无任何变化。
}) as z<{
  adapter: string;
  staticPath: string;
  provider: string;
  apiEndpoint: string;
  warmupIntervalMs: number;
  cacheDurationMs: number;
  fetchTimeoutMs: number;
  autoReload: boolean;
  maxAgeDays: number;
  maxSizeMB: number;
  trendRetentionDays: number;
}>;

/** 只按「是字符串就透传」归一的键（键集即语义，勿把别类键塞进来）。 */
const STRING_KEYS = [
  "adapter",
  "staticPath",
  "provider",
  "apiEndpoint",
  "apiKey",
  "historyDir",
] as const satisfies readonly (keyof NormalizedConfig)[];

/** 数值键的接受条件：finite=任意有限数；positiveInt=正整数（0 与负数一律非法）。 */
type AcceptKind = "finite" | "positiveInt";

/** 一把数值键的归一规则。 */
interface NumberKeyRule {
  readonly key: keyof NormalizedConfig;
  readonly accept: AcceptKind;
  /** 下界（含），缺省即不设下界。 */
  readonly min?: number;
  /** 上界（含），缺省即不设上界。 */
  readonly max?: number;
}

/**
 * 数值键的逐条规则。表是二维的（接受条件 + 上下界各自独立），不是 key→fn 的一维映射：
 * 五把数值键有三种互不相同的接受语义——仅下界（warmup/cache）、仅上界（maxSizeMB，
 * 负数合法）、正整数且有上界（maxAgeDays/trendRetentionDays）。压成一维表就得把三种
 * 语义里的两种牺牲掉，故按规则表逐条声明。
 *
 * 上下界数值与上面 COUNT_LIMITS 同源，config-matrix 门禁的 N4 断言它们与 DEFAULT_CONFIG 一致。
 */
const NUMBER_KEY_RULES = [
  // warmupIntervalMs / cacheDurationMs 只有下界（机器极限不是产品约束，不设上界）
  { key: "warmupIntervalMs", accept: "finite", min: 60000 },
  { key: "cacheDurationMs", accept: "finite", min: 5000 },
  { key: "maxSizeMB", accept: "finite", max: 500 },
  // maxAgeDays 仅接受正整数——<=0 会令 maybePrune 下界落在未来（历史被全量清理）、
  // 面板查询区间 start>end 永空；非法一律回落默认值，上界 365 维持既有 clamp
  { key: "maxAgeDays", accept: "positiveInt", max: 365 },
  // trend 聚合保留天数——仅正整数（上界 3650≈10 年），非法回落默认 180
  { key: "trendRetentionDays", accept: "positiveInt", max: 3650 },
] as const satisfies readonly NumberKeyRule[];

/** 值是否满足该键的接受条件（承担类型收窄，故返回类型谓词而非 boolean）。 */
function isAcceptedNumber(v: unknown, accept: AcceptKind): v is number {
  if (accept === "finite") return typeof v === "number" && Number.isFinite(v);
  return typeof v === "number" && Number.isInteger(v) && v > 0;
}

/** 按规则把已接受的值夹进上下界（先下后上，两端各自可缺省）。 */
function clampNumber(v: number, rule: NumberKeyRule): number {
  let out = v;
  if (rule.min !== undefined) out = Math.max(rule.min, out);
  if (rule.max !== undefined) out = Math.min(rule.max, out);
  return out;
}

/** 字符串键：非字符串一律沿用默认值（不做空串/空白归一，语义同原实现）。 */
function applyStringKeys(base: NormalizedConfig, cfg: Record<string, unknown>): void {
  for (const key of STRING_KEYS) {
    const v = cfg[key];
    if (typeof v === "string") base[key] = v;
  }
}

/** 布尔键：仅 autoReload（fetchTimeoutMs 固定 5s 不开放配置：远端慢时 2s 频繁超时）。 */
function applyBooleanKeys(base: NormalizedConfig, cfg: Record<string, unknown>): void {
  if (typeof cfg.autoReload === "boolean") base.autoReload = cfg.autoReload;
}

/** 数值键：逐条走自己的接受条件与上下界，非法值不覆写（回落默认值）。 */
function applyNumberKeys(base: NormalizedConfig, cfg: Record<string, unknown>): void {
  for (const rule of NUMBER_KEY_RULES) {
    const v = cfg[rule.key];
    if (isAcceptedNumber(v, rule.accept)) base[rule.key] = clampNumber(v, rule);
  }
}

export function normalizeConfig(input: unknown): NormalizedConfig {
  const base = { ...DEFAULT_CONFIG };
  if (typeof input !== "object" || input === null) return base;
  const cfg = input as Record<string, unknown>;
  applyStringKeys(base, cfg);
  applyBooleanKeys(base, cfg);
  applyNumberKeys(base, cfg);
  return base;
}

packages/dsh-provider-usage/src/shared/u.source:
/**
 * dsh-provider-usage — 胶囊位置 UI 配置（纯函数 + 持久化文件读写）。
 *
 * 自 index.ts 抽离，导出面由 index.ts 转发 re-export
 * 保持不变（外部消费者仍从 lib/index.js 导入）。
 */

import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { DEFAULT_Z_INDEX_BASE, clampZIndexBase } from "./placement-math.ts";

/** 胶囊/面板位置配置（设置页「胶囊位置」区维护，持久化到 historyRoot/ui.json）。 */
export interface UiPlacementConfig {
  /** 胶囊锚点：右上/左上/右下/左下（默认 top-right = 历史行为）。 */
  placement: "top-right" | "top-left" | "bottom-right" | "bottom-left";
  /** 胶囊水平偏移 px（对 left 或 right 生效）。 */
  offsetX: number;
  /** 胶囊垂直偏移 px（对 top 或 bottom 生效）。 */
  offsetY: number;
  /** 面板相对胶囊下缘的垂直间距 px。 */
  panelOffsetY: number;
  /** 层级基准（clamp 1–9000；胶囊与点击后弹出的主面板 computed z-index 均取该配置值）。 */
  zIndexBase: number;
}

/** 默认胶囊/面板位置：右上角、右侧对齐（offsetX=0 贴容器右缘）；offsetY=48 让
 *  胶囊默认位于 dsh-mcp-manager 浮窗（默认 top-right、offsetY=8、高约 26px）下方，
 *  保证两胶囊默认互不重叠（去避让后以固定默认值错开；跨包避让契约，
 *  不可回退——见两包 README 与 docs/DEVELOPMENT.md「浮窗移动端适配约定」）。 */
export const DEFAULT_UI_CONFIG: UiPlacementConfig = {
  placement: "top-right",
  offsetX: 0,
  offsetY: 48,
  panelOffsetY: 10,
  zIndexBase: DEFAULT_Z_INDEX_BASE,
};

const UI_PLACEMENTS: UiPlacementConfig["placement"][] = [
  "top-right",
  "top-left",
  "bottom-right",
  "bottom-left",
];

/** 校验并归一化客户端提交的 UI 配置（非法值回退默认；offset 限制 0–2000）。 */
export function normalizeUiConfig(raw: unknown): UiPlacementConfig {
  const src = (typeof raw === "object" && raw !== null ? raw : {}) as Record<string, unknown>;
  const placement = UI_PLACEMENTS.includes(src.placement as UiPlacementConfig["placement"])
    ? (src.placement as UiPlacementConfig["placement"])
    : DEFAULT_UI_CONFIG.placement;
  const clamp = (v: unknown, dflt: number): number => {
    const n = typeof v === "number" && Number.isFinite(v) ? v : Number(v);
    return Number.isFinite(n) ? Math.min(2000, Math.max(0, Math.round(n))) : dflt;
  };
  return {
    placement,
    offsetX: clamp(src.offsetX, DEFAULT_UI_CONFIG.offsetX),
    offsetY: clamp(src.offsetY, DEFAULT_UI_CONFIG.offsetY),
    panelOffsetY: clamp(src.panelOffsetY, DEFAULT_UI_CONFIG.panelOffsetY),
    // 层级基准 clamp 到 [1,9000]，非法回退默认（与 mcp-manager 同构语义）。
    zIndexBase: clampZIndexBase(src.zIndexBase, DEFAULT_UI_CONFIG.zIndexBase),
  };
}

// 面板垂直定位纯函数改由 interface.ts 直接从 placement-math.ts 转出（单源，
// 此处不再中转——目录门面是唯一出口）。

/** UI 配置持久化文件（historyRoot 下，0600）。 */
export function uiConfigFile(root: string): string {
  return join(root, "ui.json");
}

/** 读取 UI 配置（文件缺失/损坏回退默认）。 */
export async function readUiConfig(root: string): Promise<UiPlacementConfig> {
  try {
    const text = await readFile(uiConfigFile(root), "utf8");
    return normalizeUiConfig(JSON.parse(text));
  } catch {
    return { ...DEFAULT_UI_CONFIG };
  }
}

/** 原子写 UI 配置（tmp + rename，0600；根目录缺失时先建）。 */
export async function writeUiConfig(root: string, cfg: UiPlacementConfig): Promise<void> {
  const file = uiConfigFile(root);
  await mkdir(root, { recursive: true });
  const tmp = `${file}.${Date.now()}.tmp`;
  await writeFile(tmp, JSON.stringify(normalizeUiConfig(cfg)), { mode: 0o600 });
  await rename(tmp, file);
}

packages/dsh-provider-usage/test/unit/tr.source:
/**
 * dsh-provider-usage — unit：#503 会话用量趋势（M1 数据层）。
 *
 * 覆盖（方案定稿 v1.2 记账口径 + 两级聚合 + 分片存储 + tracker 组合）：
 * - collector：usage 定稿主信号 / text-delta 热路径不计 / 重复 usage 校正不重记 /
 *   retry 逐次计（新 header 边界）/ message 补记与校正 / interrupted /
 *   归属缺失入未识别桶 / message.source 副源 / turn-end 定稿记忆保留（防乱序双算）/
 *   turn 计数 / tool 计数 / 分级 TTL / 会话销毁清理 /
 *   非结算事件 default 忽略（developer/message·end-seed 等）/
 *   fork 仅计 live 新增（seed 边界不产出·子会话独立起算·无 seq 过滤分支）/
 *   用量二选一回归（顶层 ?? stream 末条·末条胜出·非裸形态不认）
 * - 评审修复：P2-1 counter 记账 time 取 event.time / P2-2 message 补记定稿后
 *   headerSeen 对称重置（迟到 usage 不双算）/ P2-3 done 记忆 Map 化（retry 记忆 +
 *   TREND_DONE_MAX 淘汰）/ P2-6 归属不一致 onAnomaly 告警（不覆盖主源）
 * - aggregator：null 语义求和 / 日切压实（cells 不动）/ rebuild / mergeAggRows /
 *   日/周/月序列（周一锚点、月区间、空日 null、provider 过滤）/ 时钟回拨旧日落桶
 * - store：明细 roundtrip / 坏行跳过 / 聚合原子写 / prune /
 *   P1-3 appendRows 成功日集合（部分失败不重复 append）/ P2-4 坏行校验拒绝 /
 *   P2-7 writeAggDay 清理同日残留 tmp
 * - 交叉：P0-1 HistoryStore.pruneAll 不误删 trend 分片
 * - tracker：启动重建（聚合权威）/ 过去日明细自愈 / 当日明细防二次落盘 /
 *   防抖刷盘 / dispose await 刷盘 / 日切压实与重启不双算 / 迟到旧日行合并防覆盖
 * - 复核 M1（#633）：混存分片重启重建 dirDays 恢复（dir 行真读回）/ 自愈压实
 *   dir 行 pending 同源折算不丢 / pruneDays 联动删除 dirDays
 * - 复核 P1-1（#633）：dirDays 单源化——过去日不随 dropPending 删除（跨天柱
 *   不失）/ rebuild 明细计数行平行折算（同日重启续 apply 双算防线）/ correct
 *   校正双面同步（dirDays 与 cells 不漂移）
 * - config：trendRetentionDays 归一化
 *
