      peakKey: sumReused.peakKey,
      top: sumReused.top,
      prevTotal: sumReused.prevTotal,
      prevComplete: sumReused.prevComplete,
    });
    sumSubset = snapshot({
      total: sum.total,
      calls: sum.calls,
      peakKey: sum.peakKey,
      top: sum.top,
