      makeCollector: (o) => new TrendCollector(o),
      root,
      now: () => T0,
      flushDebounceMs: 50,
    });
    // buckets() 按请求日键必有桶（数据刚写入），find 命中是前置语义。
    const b = tracker.buckets().find((d) => d.day === day1)!;
    cellCalls = b.providers[0].cell.calls;
