describe("#633 A2(a)：旧格式 fixture 重建（聚合权威 + 当日明细不重写）", () => {
  let pastBucketExists: boolean;
  let pastCell: {
    input: number | null;
    output: number | null;
    cacheRead: number | null;
    cacheWrite: number | null;
    calls: number;
    turns: number;
    toolCalls: number;
