  it("history 路由已注册", () => {
    expect(historyR).toBeTruthy();
  });

  it("无候选 provider 报 no-adapter", () => {
    expect(noAdpBody.reason).toBe("no-adapter");
  });

  it("无候选不带占位 HTML", () => {
