}

/** 唯一启用探针：同 provider 有两行以上 enabled=true 即双启用（必须红）。 */
function hasDualEnabled(
  infos: Array<{ providers: string[]; enabled: boolean }>,
  provider: string,
): boolean {
  return infos.filter((i) => i.providers.includes(provider) && i.enabled).length > 1;
}

